Skill 2 shows one Walsh peak of z=5.0, with bit 0 xor bit 2 of the answer following a parity of input bits, which could be a conditional bit rule. I am testing low-degree polynomials over GF(2), that peak's conditions, and whether rows or columns fall into groups.
```python
import numpy as np, itertools, time
T=np.load("T.npy"); rng=np.random.default_rng(3)
Aall,Ball=np.where(T[0]>=0)
bits=np.stack([(Aall>>i)&1 for i in range(5)]+[(Ball>>i)&1 for i in range(5)],1).astype(np.uint8)
def mons(d):
  cols=[np.ones(len(bits),np.uint8)]; 
  for k in range(1,d+1):
    for c in itertools.combinations(range(10),k): cols.append(bits[:,list(c)].prod(1).astype(np.uint8))
  return np.stack(cols,1)
X=mons(2); N,D=X.shape
def solve(Xs,ys):
  M=np.concatenate([Xs,ys[:,None]],1).copy(); r=0; piv=[]
  for c in range(M.shape[1]-1):
    p=np.nonzero(M[r:,c])[0]
    if len(p)==0: continue
    p=p[0]+r; M[[r,p]]=M[[p,r]]
    o=np.nonzero(M[:,c])[0]; o=o[o!=r]; M[o]^=M[r]; piv.append(c); r+=1
    if r==M.shape[0]: break
  w=np.zeros(M.shape[1]-1,np.uint8); w[piv]=M[:len(piv),-1]; return w
t0=time.time(); 
for s in range(4):
  Y=T[s][Aall,Ball]; res=[]
  for om in range(1,8):
    y=np.array([bin(int(v)&om).count("1")%2 for v in Y],np.uint8); best=0
    for _ in range(40):
      if time.time()-t0>17: break
      i=rng.choice(N,D+6,replace=False); w=solve(X[i],y[i])
      best=max(best,float(((X@w)%2==y).mean()))
    res.append((om,round(best,3)))
  print(s,"deg2 best parity agreement",res)
